/**
 * Reference-number pattern helpers (Aktenzeichen / Vorgangsnummer).
 *
 * Mirrors the backend resolution contract for the per-form reference pattern.
 * Supported tokens:
 *   {ORG}        - organisation prefix
 *   {YEAR}       - four-digit year
 *   {SEQ}        - running sequence (per form when a per-form pattern is set)
 *   {SEQ:N}      - zero-padded sequence with width N
 *   {UUID_SHORT} - short random suffix
 *
 * These helpers are client-side only: they render a human preview of a pattern.
 * The authoritative number is generated by Drupal at submit time.
 */

/** Tokens recognised by the backend, exposed in the admin token help. */
export const REFERENCE_PATTERN_TOKENS = [
    'ORG',
    'YEAR',
    'SEQ',
    'UUID_SHORT'
] as const;

export type ReferencePatternToken = (typeof REFERENCE_PATTERN_TOKENS)[number];

/**
 * Max length of the generated reference number, matching the Drupal
 * `field_reference_number` column (`max_length: 64`). A pattern whose rendered
 * output exceeds this would be truncated at submit time.
 */
export const REFERENCE_NUMBER_MAX_LENGTH = 64;

/**
 * Returns the unrecognised `{TOKEN}` names found in a pattern (e.g. `SEQUENCE`
 * for `{SEQUENCE}`). `{SEQ:N}` is recognised. Lets the admin UI warn about typos
 * that would otherwise appear literally in every reference number.
 */
export function findUnknownReferenceTokens(pattern: string): string[] {
    const known = new Set<string>([...REFERENCE_PATTERN_TOKENS]);
    const out: string[] = [];
    for (const match of (pattern ?? '').matchAll(/\{([^}]+)\}/g)) {
        const raw = match[1] ?? '';
        const name = raw.replace(/:\d+$/, '');
        if (!known.has(name) && !out.includes(raw)) out.push(raw);
    }
    return out;
}

export interface ReferencePreviewContext {
    /** Organisation prefix sample, e.g. "MST". */
    orgPrefix?: string
    /** Year used in the preview. Defaults to the current year. */
    year?: number
    /** Sequence value used for {SEQ}. Defaults to 1. */
    sequence?: number
    /** Short uuid sample for {UUID_SHORT}. */
    uuidShort?: string
}

const SEQ_TOKEN = /\{SEQ(?::(\d+))?\}/g;

/**
 * Render a preview of a reference pattern by replacing the supported tokens
 * with sample values. Unknown tokens are left untouched so the admin can spot
 * typos in their pattern.
 */
export function renderReferencePatternPreview(
    pattern: string,
    context: ReferencePreviewContext = {}
): string {
    const trimmed = (pattern ?? '').trim();
    if (!trimmed) return '';

    const orgPrefix = (context.orgPrefix || 'ORG').trim() || 'ORG';
    const year = context.year ?? new Date().getFullYear();
    const sequence = context.sequence ?? 1;
    const uuidShort = (context.uuidShort || 'a1b2c3').trim() || 'a1b2c3';

    return trimmed
        .replace(SEQ_TOKEN, (_match, width?: string) => {
            const padWidth = width ? Math.max(0, Number.parseInt(width, 10)) : 0;
            const seq = String(sequence);
            return padWidth > 0 ? seq.padStart(padWidth, '0') : seq;
        })
        .replace(/\{ORG\}/g, orgPrefix)
        .replace(/\{YEAR\}/g, String(year))
        .replace(/\{UUID_SHORT\}/g, uuidShort);
}

/**
 * Normalise a pattern for persistence: trim whitespace. An empty result means
 * "no per-form override" and the backend falls back to the organisation pattern.
 */
export function normalizeReferencePattern(pattern: string | null | undefined): string {
    return (pattern ?? '').trim();
}
